import React from "react";

import "../../styles/roiTabs.css";
import "../../styles/RecordEntry.css";

import { NavLink, Outlet } from "react-router-dom";
export default function AutomationMetricMain() {
    return (
        <div className="container">
            <h2>Automation Metrices</h2>
            <div className="tabs">
                <NavLink className="roi-tab" to={`AutomationMetric_projects`}>Projects</NavLink>
                <NavLink className="roi-tab" to={`AutoRegression`}>Auto Regression</NavLink>
            </div>
            <Outlet />
        </div>
    );

}
